/**
 * Builds `src/generated/`: one `.svelte` component per catalog icon and `icons.ts`, which
 * exports them all.
 *
 *   node scripts/generate.ts           write the files
 *   node scripts/generate.ts --check   fail if a file is out of date or unexpected
 */
import { readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { iconComponentName, iconExportName, icons } from "@0xdolan/deq-icons";

const OUT = fileURLToPath(new URL("../src/generated/", import.meta.url));
const HEADER =
  "Generated by scripts/generate.ts from @0xdolan/deq-icons. Do not edit: run `pnpm --filter @0xdolan/deq-svelte generate`.";

/** File name → contents of every generated file. */
export function generate(): Map<string, string> {
  const files = new Map<string, string>();
  const index = [`// ${HEADER}`];
  for (const [id, icon] of Object.entries(icons)) {
    const c = iconComponentName(id);
    files.set(
      `${c}.svelte`,
      [
        `<!-- ${HEADER} -->`,
        "<!--",
        "  @component",
        `  ${icon.title} (\`${id}\`).`,
        "-->",
        '<script lang="ts">',
        `  import { ${iconExportName(id)} } from "@0xdolan/deq-icons";`,
        "",
        '  import Icon from "../Icon.svelte";',
        '  import type { DeqIconProps } from "../types.js";',
        "",
        "  let props: DeqIconProps = $props();",
        "</script>",
        "",
        `<Icon icon={${iconExportName(id)}} {...props} />`,
        "",
      ].join("\n"),
    );
    index.push(`export { default as ${c} } from "./${c}.svelte";`);
  }
  files.set("icons.ts", `${index.join("\n")}\n`);
  return files;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const files = generate();
  const existing = readdirSync(OUT);
  if (process.argv.includes("--check")) {
    const stale = [
      ...[...files]
        .filter(([f, t]) => !existing.includes(f) || readFileSync(join(OUT, f), "utf8") !== t)
        .map(([f]) => f),
      ...existing.filter((f) => !files.has(f)),
    ];
    if (stale.length > 0) {
      console.error(
        `out of date: ${stale.join(", ")}: run \`pnpm --filter @0xdolan/deq-svelte generate\``,
      );
      process.exit(1);
    }
  } else {
    for (const f of existing) if (!files.has(f)) rmSync(join(OUT, f));
    for (const [f, t] of files) writeFileSync(join(OUT, f), t);
  }
}
